  1	package shop;
  2	
  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	import java.time.Clock;
  6	import java.util.List;
  7	import shop.app.CheckoutService;
  8	import shop.app.CreditEffect;
  9	import shop.app.Notifier;
 10	import shop.app.OrderService;
 11	import shop.app.PaymentApprovedNoticeEffect;
 12	import shop.app.QueryService;
 13	import shop.app.TransLogClient;
 14	import shop.db.Database;
 15	import shop.db.Schema;
 16	import shop.domain.CarrierGateway;
 17	import shop.domain.Rules;
 18	import shop.web.Api;
 19	
 20	public final class Main {
 21	    private Main() {
 22	    }
 23	
 24	    /** Wires the whole service on top of a database. */
 25	    public static Api wire(Database db, CarrierGateway carrier, Clock clock) {
 26	        Rules rules = Rules.standard(carrier);
 27	        CheckoutService checkout = new CheckoutService(db, rules);
 28	        Notifier notifier = new Notifier();
 29	        OrderService orders = new OrderService(db, checkout, clock, notifier,
 30	                List.of(new CreditEffect(), new PaymentApprovedNoticeEffect(notifier)));
 31	        return new Api(checkout, orders, new QueryService(db));
 32	    }
 33	
 34	    public static void main(String[] args) throws Exception {
 35	        HikariConfig config = new HikariConfig();
 36	        config.setJdbcUrl(System.getenv("DB_URL"));
 37	        config.setUsername(System.getenv("DB_USER"));
 38	        config.setPassword(System.getenv("DB_PASSWORD"));
 39	        config.setMaximumPoolSize(10);
 40	        config.setInitializationFailTimeout(-1);
 41	        HikariDataSource dataSource = new HikariDataSource(config);
 42	
 43	        initSchemaWithRetry(dataSource);
 44	
 45	        String port = System.getenv("PORT");
 46	        Database db = new Database(dataSource);
 47	        wire(db, new TransLogClient(System.getenv("TRANSLOG_URL")), Clock.systemUTC())
 48	                .create().start(port == null || port.isBlank() ? 8080 : Integer.parseInt(port.trim()));
 49	    }
 50	
 51	    private static void initSchemaWithRetry(HikariDataSource dataSource) throws Exception {
 52	        long deadline = System.currentTimeMillis() + 120_000;
 53	        while (true) {
 54	            try {
 55	                Schema.init(dataSource);
 56	                return;
 57	            } catch (Exception e) {
 58	                if (System.currentTimeMillis() > deadline) {
 59	                    throw e;
 60	                }
 61	                System.err.println("Database not ready, retrying: " + e.getMessage());
 62	                Thread.sleep(2000);
 63	            }
 64	        }
 65	    }
 66	}
