 69	import java.util.LinkedHashMap;
 70	import java.util.Map;
 71	import java.util.Optional;
 72	import java.util.function.Function;
 73	
 74	/** Lookup of pluggable business rules by their code. */
 75	public final class Registry<T> {
 76	    private final Map<String, T> byCode = new LinkedHashMap<>();
 77	
 78	    public Registry(Function<T, String> codeOf, Iterable<? extends T> items) {
 79	        for (T item : items) {
 80	            byCode.put(codeOf.apply(item), item);
 81	        }
 82	    }
 83	
 84	    public Optional<T> find(String code) {
 85	        return code == null ? Optional.empty() : Optional.ofNullable(byCode.get(code));
 86	    }
 87	}
