 90	import java.math.BigDecimal;
 91	import java.math.RoundingMode;
 92	
 93	public interface ShippingMethod {
 94	    record Request(String zipCode, BigDecimal weightKg, Region region) {
 95	        public int weightGrams() {
 96	            return weightKg.multiply(BigDecimal.valueOf(1000)).setScale(0, RoundingMode.HALF_UP).intValueExact();
 97	        }
 98	    }
 99	
100	    record Quote(BigDecimal cost, int days) {
101	    }
102	
103	    String code();
104	
105	    /** Refuses with SHIPPING_METHOD_UNAVAILABLE or CARRIER_UNAVAILABLE when it cannot serve the order. */
106	    Quote quote(Request request);
107	
108	    /** False when there is no freight at all (e.g. store pickup). */
109	    default boolean chargesFreight() {
110	        return true;
111	    }
112	
113	    /** False when the tier's free-shipping perk does not cover this method (third-party courier). */
114	    default boolean coveredByTierFreeShipping() {
115	        return true;
116	    }
117	
118	    /** Fixed price and lead time. */
119	    record Fixed(String code, BigDecimal cost, int days, boolean chargesFreight, boolean coveredByTierFreeShipping,
120	                 BigDecimal maxWeightKg) implements ShippingMethod {
121	        @Override
122	        public Quote quote(Request request) {
123	            if (maxWeightKg != null && request.weightKg().compareTo(maxWeightKg) > 0) {
124	                throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
125	            }
126	            return new Quote(cost, days);
127	        }
128	    }
129	
130	    /** Priced by an external carrier; the distribution center adds days in some regions. */
131	    record Carrier(String code, CarrierGateway gateway, String service) implements ShippingMethod {
132	        @Override
133	        public Quote quote(Request request) {
134	            CarrierGateway.Quote q;
135	            try {
136	                q = gateway.quote(request.zipCode(), request.weightGrams(), service)
137	                        .orElseThrow(() -> ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE"));
138	            } catch (CarrierGateway.UnavailableException e) {
139	                throw new ApiException("CARRIER_UNAVAILABLE", 503);
140	            }
141	            return new Quote(q.cost(), q.days() + request.region().extraDispatchDays());
142	        }
143	    }
144	}
