147	import java.math.BigDecimal;
148	import java.util.List;
149	import java.util.function.BooleanSupplier;
150	
151	public interface Coupon {
152	    record Context(String cpf, List<CartLine> lines, BigDecimal subtotal, ShippingMethod shipping,
153	                   BigDecimal shippingCost, BooleanSupplier firstPurchase) {
154	    }
155	
156	    String code();
157	
158	    /** Discount before the 30% cap; refuses with COUPON_NOT_APPLICABLE when the order does not qualify. */
159	    BigDecimal discount(Context context);
160	
161	    static ApiException notApplicable() {
162	        return ApiException.unprocessable("COUPON_NOT_APPLICABLE");
163	    }
164	
165	    record PercentOfProducts(String code, BigDecimal rate, boolean firstPurchaseOnly) implements Coupon {
166	        @Override
167	        public BigDecimal discount(Context c) {
168	            if (firstPurchaseOnly && !c.firstPurchase().getAsBoolean()) {
169	                throw notApplicable();
170	            }
171	            return Money.round(c.subtotal().multiply(rate));
172	        }
173	    }
174	
175	    record FixedOffProducts(String code, BigDecimal amount, BigDecimal minimumSubtotal) implements Coupon {
176	        @Override
177	        public BigDecimal discount(Context c) {
178	            if (c.subtotal().compareTo(minimumSubtotal) < 0) {
179	                throw notApplicable();
180	            }
181	            return amount;
182	        }
183	    }
184	
185	    record FreeShipping(String code) implements Coupon {
186	        @Override
187	        public BigDecimal discount(Context c) {
188	            if (!c.shipping().chargesFreight()) {
189	                throw notApplicable();
190	            }
191	            return c.shippingCost();
192	        }
193	    }
194	
195	    /** Every {@code groupSize}-th unit of the same product is free. */
196	    record EveryNthFree(String code, int groupSize) implements Coupon {
197	        @Override
198	        public BigDecimal discount(Context c) {
199	            BigDecimal total = Money.ZERO;
200	            for (CartLine line : c.lines()) {
201	                int free = line.quantity() / groupSize;
202	                total = total.add(line.product().price().multiply(BigDecimal.valueOf(free)));
203	            }
204	            return Money.round(total);
205	        }
206	    }
207	}

