 80	public record ClubTier(String code, BigDecimal creditRate, boolean freeShipping, BigDecimal giftAbove) {
 81	
 82	    public BigDecimal credit(BigDecimal productsSubtotal) {
 83	        return Money.round(productsSubtotal.multiply(creditRate));
 84	    }
