 90	package shop.domain;
 91	
 92	import java.math.BigDecimal;
 93	import java.util.Optional;
 94	
 95	/** Delivery region: insurance pricing and extra dispatch days of the distribution center. */
 96	public enum Region {
 97	    SOUTHEAST("0.01", null, 0),
 98	    SOUTH("0.01", null, 0),
 99	    MIDWEST("0.015", null, 0),
100	    NORTH("0.025", "30.00", 3),
101	    NORTHEAST("0.02", "30.00", 2);
102	
103	    private final BigDecimal insuranceRate;
104	    private final BigDecimal insuranceCap;
105	    private final int extraDispatchDays;
106	
107	    Region(String insuranceRate, String insuranceCap, int extraDispatchDays) {
108	        this.insuranceRate = new BigDecimal(insuranceRate);
109	        this.insuranceCap = insuranceCap == null ? null : new BigDecimal(insuranceCap);
110	        this.extraDispatchDays = extraDispatchDays;
111	    }
112	
113	    public BigDecimal insurance(BigDecimal productsSubtotal) {
114	        BigDecimal value = Money.round(productsSubtotal.multiply(insuranceRate));
115	        return insuranceCap != null && value.compareTo(insuranceCap) > 0 ? insuranceCap : value;
116	    }
117	
118	    public int extraDispatchDays() {
119	        return extraDispatchDays;
120	    }
121	
122	    public static Optional<Region> parse(String code) {
123	        for (Region r : values()) {
124	            if (r.name().equals(code)) {
125	                return Optional.of(r);
126	            }
127	        }
128	        return Optional.empty();
129	    }
130	}
