136	/** The business rules currently in force, keyed by the codes the API uses. */
137	public record Rules(Registry<ClubTier> tiers, Registry<ShippingMethod> shipping, Registry<Coupon> coupons,
138	                    Registry<PaymentMethod> payments, BigDecimal couponDiscountCap) {
139	
140	    public static Rules standard(CarrierGateway carrier) {
141	        List<ClubTier> tiers = List.of(
142	                new ClubTier("BRONZE", new BigDecimal("0"), false, null),
143	                new ClubTier("SILVER", new BigDecimal("0.02"), false, null),
144	                new ClubTier("GOLD", new BigDecimal("0.05"), true, Money.of("500.00")));
145	        List<ShippingMethod> shipping = List.of(
146	                new ShippingMethod.Carrier("ECONOMY", carrier, "STD"),
147	                new ShippingMethod.Carrier("EXPRESS", carrier, "EXP"),
148	                new ShippingMethod.Fixed("STORE_PICKUP", Money.ZERO, 1, false, true, null),
149	                new ShippingMethod.Fixed("COURIER", Money.of("18.00"), 0, true, false, new BigDecimal("5")));
150	        List<Coupon> coupons = List.of(
151	                new Coupon.PercentOfProducts("WELCOME10", new BigDecimal("0.10"), true),
152	                new Coupon.FixedOffProducts("MINUS50", Money.of("50.00"), Money.of("300.00")),
153	                new Coupon.FreeShipping("FREESHIPPING"),
154	                new Coupon.EveryNthFree("BUY3PAY2", 3));
155	        List<PaymentMethod> payments = List.of(
156	                new PaymentMethod.Pix("PIX", new BigDecimal("0.05")),
157	                new PaymentMethod.CreditCard("CREDIT_CARD", 12, 3, new BigDecimal("0.0199")),
158	                new PaymentMethod.BankSlip("BANK_SLIP", Money.of("3.49"), Money.of("1000.00")));
159	        return new Rules(
160	                new Registry<>(ClubTier::code, tiers),
161	                new Registry<>(ShippingMethod::code, shipping),
162	                new Registry<>(Coupon::code, coupons),
163	                new Registry<>(PaymentMethod::code, payments),
164	                new BigDecimal("0.30"));
165	    }
166	}
