  8	    }
  9	
 10	    String code();
 11	
 12	    boolean acceptsInstallments(int installments);
 13	
 14	    /** Refuses with PAYMENT_METHOD_UNAVAILABLE when the method cannot be used for this total. */
 15	    default void checkAvailable(BigDecimal orderTotal) {
 16	    }
 17	
 18	    Settlement settle(BigDecimal orderTotal, int installments, boolean couponUsed);
 19	
 20	    record Pix(String code, BigDecimal discountRate) implements PaymentMethod {
 21	        @Override
 22	        public boolean acceptsInstallments(int n) {
 23	            return n == 1;
 24	        }
 25	
 26	        @Override
 27	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
 28	            BigDecimal discount = couponUsed ? Money.ZERO : Money.round(total.multiply(discountRate));
 29	            BigDecimal result = total.subtract(discount);
 30	            return new Settlement(result, result);
 31	        }
 32	    }
 33	
 34	    record BankSlip(String code, BigDecimal fee, BigDecimal maximumTotal) implements PaymentMethod {
 35	        @Override
 36	        public boolean acceptsInstallments(int n) {
 37	            return n == 1;
 38	        }
 39	
 40	        @Override
 41	        public void checkAvailable(BigDecimal total) {
 42	            if (total.compareTo(maximumTotal) > 0) {
 43	                throw ApiException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
 44	            }
 45	        }
 46	
 47	        @Override
 48	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
 49	            BigDecimal result = total.add(fee);
 50	            return new Settlement(result, result);
 51	        }
 52	    }
 53	
 54	    /** Interest-free up to {@code freeUntil} installments, then Price table. */
 55	    record CreditCard(String code, int maxInstallments, int freeUntil, BigDecimal monthlyRate)
 56	            implements PaymentMethod {
 57	        @Override
 58	        public boolean acceptsInstallments(int n) {
 59	            return n >= 1 && n <= maxInstallments;
 60	        }
 61	
 62	        @Override
 63	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
 64	            if (n <= freeUntil) {
 65	                return new Settlement(total, Money.round(total.divide(BigDecimal.valueOf(n), MathContext.DECIMAL128)));
 66	            }
 67	            BigDecimal growth = BigDecimal.ONE.add(monthlyRate).pow(n, MathContext.DECIMAL128);
 68	            // total * i / (1 - (1+i)^-n)  ==  total * i * (1+i)^n / ((1+i)^n - 1)
 69	            BigDecimal installment = Money.round(total.multiply(monthlyRate).multiply(growth)
 70	                    .divide(growth.subtract(BigDecimal.ONE), MathContext.DECIMAL128));
 71	            return new Settlement(installment.multiply(BigDecimal.valueOf(n)), installment);
 72	        }
 73	    }
 74	}
