  1	package shop.app;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import java.math.BigDecimal;
  5	import java.util.ArrayList;
  6	import java.util.HashSet;
  7	import java.util.List;
  8	import java.util.Map;
  9	import java.util.Set;
 10	import shop.db.Database;
 11	import shop.domain.ApiException;
 12	import shop.domain.CartLine;
 13	import shop.domain.ClubTier;
 14	import shop.domain.Coupon;
 15	import shop.domain.Money;
 16	import shop.domain.OrderItem;
 17	import shop.domain.PaymentMethod;
 18	import shop.domain.Product;
 19	import shop.domain.Region;
 20	import shop.domain.Rules;
 21	import shop.domain.ShippingMethod;
 22	import shop.domain.Summary;
 23	
 24	/** Validates a purchase and computes its summary. Shared by the summary endpoint and order registration. */
 25	public final class CheckoutService {
 26	    public record Checkout(String cpf, String email, List<OrderItem> items, Summary summary) {
 27	    }
 28	
 29	    private final Database db;
 30	    private final Rules rules;
 31	
 32	    public CheckoutService(Database db, Rules rules) {
 33	        this.db = db;
 34	        this.rules = rules;
 35	    }
 36	
 37	    public Checkout prepare(JsonNode body) {
 38	        // 1. basic shape
 39	        if (!body.isObject()) {
 40	            throw invalid("INVALID_ORDER");
 41	        }
 42	        JsonNode customer = body.path("customer");
 43	        String cpf = text(customer.path("cpf"));
 44	        String email = text(customer.path("email"));
 45	        List<OrderItem> items = parseItems(body.path("items"));
 46	        if (cpf == null || email == null) {
 47	            throw invalid("INVALID_ORDER");
 48	        }
 49	
 50	        // 2-4. products
 51	        List<CartLine> lines = loadLines(items);
 52	
 53	        // 5-8. simple fields
 54	        ClubTier tier = rules.tiers().find(text(body.path("clubTier")))
 55	                .orElseThrow(() -> invalid("INVALID_CLUB_TIER"));
 56	        Region region = Region.parse(text(body.path("region"))).orElseThrow(() -> invalid("INVALID_REGION"));
 57	        String zip = text(body.path("zipCode"));
 58	        if (zip == null || !zip.matches("[0-9]{8}")) {
 59	            throw invalid("INVALID_ZIP_CODE");
 60	        }
 61	        ShippingMethod shipping = rules.shipping().find(text(body.path("shippingMethod")))
 62	                .orElseThrow(() -> invalid("INVALID_SHIPPING_METHOD"));
 63	
 64	        // 9-10. shipping quote
 65	        BigDecimal subtotal = Money.round(lines.stream().map(CartLine::total).reduce(BigDecimal.ZERO, BigDecimal::add));
 66	        BigDecimal weightKg = lines.stream().map(CartLine::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
 67	        ShippingMethod.Quote quote = shipping.quote(new ShippingMethod.Request(zip, weightKg, region));
 68	        BigDecimal shippingCost = tier.freeShipping() && shipping.coveredByTierFreeShipping()
 69	                ? Money.ZERO : Money.round(quote.cost());
 70	
 71	        // 11-12. coupon
 72	        JsonNode couponNode = body.path("coupon");
 73	        boolean couponUsed = !couponNode.isMissingNode() && !couponNode.isNull();
 74	        BigDecimal couponDiscount = Money.ZERO;
 75	        if (couponUsed) {
 76	            Coupon coupon = rules.coupons().find(couponNode.isTextual() ? couponNode.asText() : null)
 77	                    .orElseThrow(() -> invalid("INVALID_COUPON"));
 78	            Coupon.Context context = new Coupon.Context(cpf, lines, subtotal, shipping, shippingCost,
 79	                    () -> !db.tx(d -> d.hasCompletedPurchase(cpf)));
 80	            BigDecimal cap = Money.round(subtotal.multiply(rules.couponDiscountCap()));
 81	            couponDiscount = Money.round(coupon.discount(context).min(cap));
 82	        }
 83	
 84	        // 13-15. payment
 85	        PaymentMethod payment = rules.payments().find(text(body.path("paymentMethod")))
 86	                .orElseThrow(() -> invalid("INVALID_PAYMENT_METHOD"));
 87	        int installments = parseInstallments(body.path("installments"), payment);
 88	        BigDecimal insurance = region.insurance(subtotal);
 89	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
 90	        payment.checkAvailable(orderTotal);
 91	        PaymentMethod.Settlement settlement = payment.settle(orderTotal, installments, couponUsed);
 92	
 93	        Summary summary = new Summary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
 94	                Money.round(settlement.finalTotal().subtract(orderTotal)), Money.round(settlement.finalTotal()),
 95	                installments, Money.round(settlement.installmentAmount()), tier.credit(subtotal),
 96	                tier.gift(subtotal));
 97	        return new Checkout(cpf, email, items, summary);
 98	    }
 99	
100	    private static List<OrderItem> parseItems(JsonNode node) {
101	        if (!node.isArray() || node.isEmpty()) {
102	            throw invalid("INVALID_ORDER");
103	        }
104	        List<OrderItem> items = new ArrayList<>();
105	        Set<String> seen = new HashSet<>();
106	        for (JsonNode item : node) {
107	            String sku = text(item.path("sku"));
108	            JsonNode quantity = item.path("quantity");
109	            if (sku == null || !seen.add(sku) || !quantity.isIntegralNumber() || !quantity.canConvertToInt()
110	                    || quantity.intValue() <= 0) {
111	                throw invalid("INVALID_ORDER");
112	            }
113	            items.add(new OrderItem(sku, quantity.intValue()));
114	        }
115	        return items;
116	    }
117	
118	    private List<CartLine> loadLines(List<OrderItem> items) {
119	        Map<String, Product> products = db.tx(d -> d.products(items.stream().map(OrderItem::sku).toList()));
120	        List<CartLine> lines = new ArrayList<>();
121	        for (OrderItem item : items) {
122	            Product p = products.get(item.sku());
123	            if (p == null) {
124	                throw invalid("UNKNOWN_PRODUCT");
125	            }
126	            lines.add(new CartLine(p, item.quantity()));
127	        }
128	        if (lines.stream().anyMatch(l -> l.product().discontinued())) {
129	            throw invalid("PRODUCT_DISCONTINUED");
130	        }
131	        if (lines.stream().anyMatch(l -> l.product().stock() < l.quantity())) {
132	            throw invalid("INSUFFICIENT_STOCK");
133	        }
134	        return lines;
135	    }
136	
137	    private static int parseInstallments(JsonNode node, PaymentMethod payment) {
138	        int installments = 1;
139	        if (!node.isMissingNode() && !node.isNull()) {
140	            if (!node.isIntegralNumber() || !node.canConvertToInt()) {
141	                throw invalid("INVALID_INSTALLMENTS");
142	            }
143	            installments = node.intValue();
144	        }
145	        if (!payment.acceptsInstallments(installments)) {
146	            throw invalid("INVALID_INSTALLMENTS");
147	        }
148	        return installments;
149	    }
150	
151	    /** The text of a JSON string, or null if absent, not a string or blank. */
152	    static String text(JsonNode node) {
153	        return node.isTextual() && !node.asText().isBlank() ? node.asText() : null;
154	    }
155	
156	    private static ApiException invalid(String code) {
157	        return ApiException.unprocessable(code);
158	    }
159	}
