454	import java.math.BigDecimal;
455	import java.net.URI;
456	import java.net.URLEncoder;
457	import java.net.http.HttpClient;
458	import java.net.http.HttpRequest;
459	import java.net.http.HttpResponse;
460	import java.nio.charset.StandardCharsets;
461	import java.time.Duration;
462	import java.util.Optional;
463	import java.util.concurrent.CompletableFuture;
464	import java.util.concurrent.TimeUnit;
465	import shop.domain.CarrierGateway;
466	import shop.domain.Json;
467	
468	/** Quotes freight on the TransLog website. Anything unexpected, or slower than 2 seconds, means "down". */
469	public final class TransLogClient implements CarrierGateway {
470	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
471	
472	    private final String baseUrl;
473	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
474	
475	    public TransLogClient(String baseUrl) {
476	        this.baseUrl = baseUrl == null ? "" : baseUrl.replaceAll("/+$", "");
477	    }
478	
479	    @Override
480	    public Optional<Quote> quote(String zipCode, int weightGrams, String service) {
481	        CompletableFuture<HttpResponse<String>> future = null;
482	        try {
483	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
484	                    + "&weight_g=" + weightGrams + "&service=" + URLEncoder.encode(service, StandardCharsets.UTF_8));
485	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
486	            future = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
487	            HttpResponse<String> response = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
488	            if (response.statusCode() != 200) {
489	                throw new UnavailableException("TransLog answered " + response.statusCode(), null);
490	            }
491	            return parse(Json.MAPPER.readTree(response.body()));
492	        } catch (UnavailableException e) {
493	            throw e;
494	        } catch (InterruptedException e) {
495	            Thread.currentThread().interrupt();
496	            throw new UnavailableException("interrupted", e);
497	        } catch (Exception e) {
498	            throw new UnavailableException("TransLog failed", e);
499	        } finally {
500	            if (future != null) {
501	                future.cancel(true);
502	            }
503	        }
504	    }
505	
506	    private static Optional<Quote> parse(JsonNode body) {
507	        if (body == null || !body.isObject()) {
508	            throw new UnavailableException("unexpected TransLog body", null);
509	        }
510	        if (body.has("error")) {
511	            if (body.get("error").isTextual() && "ZIP_NOT_SERVED".equals(body.get("error").asText())) {
512	                return Optional.empty();
513	            }
514	            throw new UnavailableException("TransLog error " + body.get("error"), null);
515	        }
516	        JsonNode cents = body.path("price_cents");
517	        JsonNode hours = body.path("eta_hours");
518	        if (!cents.isIntegralNumber() || !hours.isIntegralNumber() || cents.asLong() < 0 || hours.asLong() < 0
519	                || !hours.canConvertToInt()) {
520	            throw new UnavailableException("unexpected TransLog quote", null);
521	        }
522	        BigDecimal cost = BigDecimal.valueOf(cents.asLong(), 2);
523	        int days = (int) ((hours.asLong() + 23) / 24);
524	        return Optional.of(new Quote(cost, days));
525	    }
526	}

