 38	/** The only place that says which operation is allowed in which status. */
 39	public final class OrderLifecycle {
 40	    public enum Operation { PAY, SHIP, DELIVER, CANCEL }
 41	
 42	    private static final Map<Operation, Map<OrderStatus, OrderStatus>> TRANSITIONS = new EnumMap<>(Operation.class);
 43	
 44	    static {
 45	        TRANSITIONS.put(Operation.PAY, Map.of(AWAITING_PAYMENT, PAID));
 46	        TRANSITIONS.put(Operation.SHIP, Map.of(PAID, SHIPPED));
 47	        TRANSITIONS.put(Operation.DELIVER, Map.of(SHIPPED, DELIVERED));
 48	        TRANSITIONS.put(Operation.CANCEL, Map.of(AWAITING_PAYMENT, CANCELLED, PAID, CANCELLED));
 49	    }
 50	
 51	    private OrderLifecycle() {
 52	    }
 53	
 54	    public static Optional<OrderStatus> next(OrderStatus current, Operation operation) {
 55	        return Optional.ofNullable(TRANSITIONS.get(operation).get(current));
 56	    }
 57	
 58	    /** Returns the next status or refuses with OPERATION_NOT_ALLOWED. */
 59	    public static OrderStatus require(OrderStatus current, Operation operation) {
 60	        return next(current, operation).orElseThrow(() -> ApiException.conflict("OPERATION_NOT_ALLOWED"));
 61	    }
 62	}
