     1	package shop.db;
     2	
     3	import java.sql.Connection;
     4	import java.sql.SQLException;
     5	import javax.sql.DataSource;
     6	
     7	public final class Database {
     8	    @FunctionalInterface
     9	    public interface Work<T> {
    10	        T run(Dao dao) throws SQLException;
    11	    }
    12	
    13	    private final DataSource dataSource;
    14	
    15	    private final boolean postgres;
    16	
    17	    public Database(DataSource dataSource) {
    18	        this.dataSource = dataSource;
    19	        try (Connection c = dataSource.getConnection()) {
    20	            this.postgres = c.getMetaData().getDatabaseProductName().toLowerCase().contains("postgres");
    21	        } catch (SQLException e) {
    22	            throw new DbException(e);
    23	        }
    24	    }
    25	
    26	    /** Runs the work in one transaction: commits if it returns, rolls back if it throws. */
    27	    public <T> T tx(Work<T> work) {
    28	        try (Connection connection = dataSource.getConnection()) {
    29	            connection.setAutoCommit(false);
    30	            try {
    31	                T result = work.run(new Dao(connection, postgres));
    32	                connection.commit();
    33	                return result;
    34	            } catch (Throwable e) {
    35	                try {
    36	                    connection.rollback();
    37	                } catch (SQLException suppressed) {
    38	                    e.addSuppressed(suppressed);
    39	                }
    40	                throw e;
    41	            }
    42	        } catch (SQLException e) {
    43	            throw new DbException(e);
    44	        }
    45	    }
    46	}
