    58	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
    59	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
    60	
    61	    private Json() {
    62	    }
    63	
    64	    public static String write(Object value) {
    65	        try {
    66	            return MAPPER.writeValueAsString(value);
    67	        } catch (JsonProcessingException e) {
    68	            throw new IllegalStateException(e);
    69	        }
    70	    }
    71	
    72	    public static <T> T read(String text, Class<T> type) {
    73	        try {
    74	            return MAPPER.readValue(text, type);
    75	        } catch (JsonProcessingException e) {
    76	            throw new IllegalStateException(e);
    77	        }
    78	    }
    79	
    80	    /** Parses a request body; anything that is not valid JSON becomes a missing node. */
    81	    public static JsonNode parseLenient(String text) {
    82	        if (text == null || text.isBlank()) {
    83	            return MissingNode.getInstance();
    84	        }
    85	        try {
    86	            return MAPPER.readTree(text);
    87	        } catch (JsonProcessingException e) {
    88	            return MissingNode.getInstance();
